// netlify/functions/generate-pdf.ts
// Server-side PDF generation using Puppeteer
// Replaces client-side @react-pdf/renderer for pixel-perfect preview match

import type { Handler } from "@netlify/functions";
import chromium from "@sparticuz/chromium";
import puppeteer, { type Browser, type Page } from "puppeteer-core";
import { withRateLimit } from "../lib/rate-limiter.js";


import { existsSync } from "fs";

// Common Chrome/Edge paths for Windows
const WINDOWS_CHROME_PATHS = [
  "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
  "C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe",
  process.env.LOCALAPPDATA + "\\Google\\Chrome\\Application\\chrome.exe",
  // Edge as fallback (Chromium-based)
  "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe",
  "C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe",
];

// Chromium executable path varies by environment
const getChromiumPath = async (): Promise<string> => {
  if (process.env.NETLIFY) {
    return await chromium.executablePath();
  }

  // Local development - find available browser
  if (process.platform === "darwin") {
    return "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
  }

  if (process.platform === "win32") {
    for (const path of WINDOWS_CHROME_PATHS) {
      if (path && existsSync(path)) {
        console.log('[PDF] Found browser at:', path);
        return path;
      }
    }
    throw new Error('Chrome/Edge not found. Please install Chrome or Edge browser.');
  }

  return "/usr/bin/google-chrome";
};

// Check if running on Netlify (production/deploy-preview)
const isNetlify = !!process.env.NETLIFY;

// Browser connection pooling - reuse browser instance across requests
let browserInstance: Browser | null = null;
let lastUsedTime = 0;
const BROWSER_IDLE_TIMEOUT = 5 * 60 * 1000; // 5 minutes

async function getBrowser() {
  const now = Date.now();

  // Close browser if idle for too long (cleanup)
  if (browserInstance && (now - lastUsedTime) > BROWSER_IDLE_TIMEOUT) {
    console.log('[PDF] Closing idle browser instance');
    try {
      await browserInstance.close();
    } catch (err) {
      console.warn('[PDF] Error closing idle browser:', err);
    }
    browserInstance = null;
  }

  // Reuse existing browser or create new one
  // Health check: verify browser is connected before reuse
  if (browserInstance) {
    try {
      const isConnected = browserInstance.isConnected();
      if (!isConnected) {
        console.log('[PDF] Browser disconnected, creating new instance');
        browserInstance = null;
      }
    } catch (err) {
      console.warn('[PDF] Browser health check failed:', err);
      browserInstance = null;
    }
  }

  if (!browserInstance) {
    console.log('[PDF] Launching new browser instance');
    browserInstance = await puppeteer.launch({
      args: isNetlify ? chromium.args : ["--no-sandbox", "--disable-setuid-sandbox"],
      defaultViewport: { width: 794, height: 1123 }, // A4 at 96dpi: 210mm × 96/25.4 ≈ 794px, 297mm × 96/25.4 ≈ 1123px
      executablePath: await getChromiumPath(),
      headless: true, // Always headless for PDF generation
    });
  }

  lastUsedTime = now;
  return browserInstance;
}

// Valid template IDs - must match registry
const VALID_TEMPLATE_IDS = [
  'modern-professional',
  'technical-engineer',
  'ats-optimized',
  'executive-professional'
] as const;

const baseHandler: Handler = async (event) => {
  if (event.httpMethod === "HEAD") {
    return { statusCode: 200, body: "" };
  }
  if (event.httpMethod !== "POST") {
    return { statusCode: 405, body: "Method Not Allowed" };
  }

  // Auth is optional for PDF generation — rate limiting via withRateLimit prevents abuse.
  // PDF is a stateless HTML→PDF render, no AI credits or user data accessed.

  let page: Page | null = null; // Declare outside try block for cleanup access

  try {
    const { html, styles, filename, templateId } = JSON.parse(event.body || "{}");
    const safeFilename = filename || `resume-optimized`;

    if (!html) {
      return { statusCode: 400, body: JSON.stringify({ error: "Missing html" }) };
    }

    // Validate templateId to prevent header injection
    const sanitizedTemplateId = VALID_TEMPLATE_IDS.includes(templateId)
      ? templateId
      : 'modern-professional';

    // Get browser from pool (eliminates cold start on subsequent requests)
    const browser = await getBrowser();
    page = await browser.newPage();

    // Set fixed viewport matching A4 (210mm x 297mm @ 96dpi)
    await page.setViewport({ width: 794, height: 1123, deviceScaleFactor: 1 });

    // Allow external resources needed for rendering (fonts, images)
    await page.setRequestInterception(false);

    // Disable JavaScript to prevent script execution from client-provided HTML
    await page.setJavaScriptEnabled(false);

    // Render the final HTML string with embedded styles
    await page.setContent(`
      <!DOCTYPE html>
      <html dir="ltr">
        <head>
          <meta charset="UTF-8">
          <style>${styles || ''}</style>
          <style>
            /* Hide elements marked as non-printable (page break indicators, etc.) */
            [data-no-print] { display: none !important; }
            
            /* Ensure exact color rendering in print mode */
            * { 
              -webkit-print-color-adjust: exact !important; 
              print-color-adjust: exact !important; 
            }

            /* Prevent section headers from orphaning at the bottom of a page.
               Works in both screen and print rendering modes. */
            h2 { break-after: avoid; }
            
            /* Remove template root padding to prevent double-padding on page 1 */
            [data-resume-preview] > div { padding-top: 0 !important; }

          </style>
        </head>
        <body>${html}</body>
      </html>
    `, { waitUntil: 'networkidle2', timeout: 30_000 });

    // Use print media so screen-only components are hidden natively.
    await page.emulateMediaType('print');

    // Dynamically extract the template's user-defined margin settings and
    // forward them to Puppeteer's native `@page` CSS, while stripping the root
    // padding to prevent double-margins on the first page.
    await page.evaluate(`(() => {
      const templateRoot = document.querySelector('[data-resume-preview] > div');
      if (templateRoot) {
        // Extract dynamically generated margins (e.g. "12.7mm")
        const pt = templateRoot.style.paddingTop || '19.05mm';
        const pb = templateRoot.style.paddingBottom || '19.05mm';
        
        // Strip padding from the DOM so it doesn't double-apply on page 1
        templateRoot.style.paddingTop = '0';
        templateRoot.style.paddingBottom = '0';
        
        // Inject an override for index.css's @page { margin: 0 } print reset.
        // Puppeteer leverages this over its local marginal configurations.
        const style = document.createElement('style');
        style.innerHTML = '@page { margin: ' + pt + ' 0 ' + pb + ' 0 !important; }';
        document.head.appendChild(style);
      }
    })()`);

    // Wait for fonts to ensure perfect rendering
    try {
      if (!browserInstance?.isConnected()) {
        throw new Error("Browser disconnected before font load.");
      }
      await page.evaluateHandle('document.fonts.ready');
      
      // Graciously wait for images to load, max 3 seconds
      await page.evaluate(async () => {
        const doc = (globalThis as any).document;
        if (!doc) return;
        const images = Array.from(doc.images) as any[];
        if (images.length === 0) return;
        await Promise.all(
          images.map((img: any) => {
            if (img.complete) return Promise.resolve();
            return new Promise((resolve) => {
              img.onload = resolve;
              img.onerror = resolve; // Ignore broken images
            });
          })
        );
      });
    } catch(e) {
      console.warn('Asset loading failed (fonts/images), attempting PDF anyway:', e);
    }

    // Generate PDF with 60s safety timeout (Netlify fn has 90s limit)
    const PDF_TIMEOUT_MS = 60_000;
    const pdfBuffer = await Promise.race([
      page.pdf({
        format: "A4",
        printBackground: true,
        // The displayHeaderFooter property ensures no browser URL headers are printed
        // in combination with standard @page margins.
        displayHeaderFooter: false,
        margin: { top: '10mm', bottom: '10mm', left: '0', right: '0' },
      }),
      new Promise<never>((_, reject) =>
        setTimeout(() => reject(new Error(`PDF generation timed out after ${PDF_TIMEOUT_MS / 1000}s`)), PDF_TIMEOUT_MS)
      ),
    ]);

    // Close page but keep browser alive for pooling
    await page.close();

    return {
      statusCode: 200,
      headers: {
        "Content-Type": "application/pdf",
        "Content-Disposition": `attachment; filename="${safeFilename}.pdf"`,
        "Cache-Control": "no-store",
      },
      body: Buffer.from(pdfBuffer).toString("base64"),
      isBase64Encoded: true,
    };
  } catch (error) {
    console.error("PDF generation error:", error);

    // Cleanup: try to close page on error (browser stays alive for pooling)
    try {
      if (page) await page.close();
    } catch (cleanupErr) {
      console.warn('[PDF] Page cleanup error:', cleanupErr);
    }

    return {
      statusCode: 500,
      body: JSON.stringify({ error: "PDF generation failed. Please try again." }),
    };
  }
};

export const handler = withRateLimit("generate-pdf", baseHandler);

import { describe, it, expect } from 'vitest';

describe('PDF Pagination Engine reproduction', () => {
  it('simulates the Intelligent Pagination Engine logic', () => {
    // We simulate block elements.
    class Block {
      public children: Block[] = [];
      public marginTop: number = 0;
      public isWrapper = false;

      constructor(
        public name: string,
        public intrinsicTop: number, // top relative to parent, ignoring margins
        public height: number
      ) {}

      // Computed top based on parent and preceding siblings' margins
      // For simplicity, we just pass the total accumulated shift
      getTop(shift: number): number {
        return this.intrinsicTop + shift + this.marginTop;
      }
      getBottom(shift: number): number {
        return this.getTop(shift) + this.height;
      }
    }

    // A flat list of blocks as returned by querySelectorAll in document order.
    // Parent comes before children.
    const blocks = {
      parent1: new Block('parent1', 0, 800),
      child1: new Block('child1', 10, 50),
      child2: new Block('child2', 100, 50),

      parent2: new Block('parent2', 800, 600), // spans 800 to 1400 (crosses 1122.5)
      child3: new Block('child3', 810, 100),   // 810 to 910
      child4: new Block('child4', 920, 150),   // 920 to 1070
      child5: new Block('child5', 1080, 200),  // 1080 to 1280 (crosses 1122.5)
      child6: new Block('child6', 1290, 100),  // 1290 to 1390
    };

    const orderedBlocks = [
      blocks.parent1,
      blocks.child1,
      blocks.child2,
      blocks.parent2,
      blocks.child3,
      blocks.child4,
      blocks.child5,
      blocks.child6
    ];

    const PAGE_HEIGHT = 1122.5;

    // We simulate getBoundingClientRect by computing top/bottom dynamically
    // In actual DOM, setting marginTop on a parent shifts itself and its children.
    // Setting marginTop on a child shifts itself, its subsequent siblings, and stretches the parent.
    // Here we'll just implement a `getRects()` builder that mimics DOM layout.

    function getLayout() {
      let currentY = 0;
      const rects = new Map<Block, {top: number, bottom: number}>();

      // Simulating normal block layout
      // parent1
      currentY += blocks.parent1.marginTop;
      rects.set(blocks.parent1, { top: currentY, bottom: currentY + 800 });
      // In a real DOM, children are relative to parent's padding edge.
      // Child1
      let p1Y = currentY;
      p1Y += blocks.child1.marginTop;
      rects.set(blocks.child1, { top: p1Y + 10, bottom: p1Y + 10 + 50 });
      p1Y += blocks.child2.marginTop;
      rects.set(blocks.child2, { top: p1Y + 100, bottom: p1Y + 100 + 50 });

      currentY += 800; // moving past parent1

      // parent2
      currentY += blocks.parent2.marginTop;
      // BUT parent2 height stretches if children push boundaries!
      // Let's just track children first
      let p2Y = currentY;
      p2Y += blocks.child3.marginTop;
      rects.set(blocks.child3, { top: p2Y + 10, bottom: p2Y + 10 + 100 });
      p2Y += blocks.child4.marginTop;
      rects.set(blocks.child4, { top: p2Y + 120, bottom: p2Y + 120 + 150 });
      p2Y += blocks.child5.marginTop;
      rects.set(blocks.child5, { top: p2Y + 280, bottom: p2Y + 280 + 200 });
      p2Y += blocks.child6.marginTop;
      rects.set(blocks.child6, { top: p2Y + 490, bottom: p2Y + 490 + 100 });

      const p2Bottom = Math.max(currentY + 600, p2Y + 490 + 100);
      rects.set(blocks.parent2, { top: currentY, bottom: p2Bottom });

      return rects;
    }

    // Run engine
    orderedBlocks.forEach(block => {
      const layout = getLayout();
      const rect = layout.get(block)!;
      const relativeTop = rect.top;
      const relativeBottom = rect.bottom;

      const startPage = Math.floor(relativeTop / PAGE_HEIGHT);
      const endPage = Math.floor(relativeBottom / PAGE_HEIGHT);

      if (startPage !== endPage && (relativeBottom - relativeTop) < PAGE_HEIGHT) {
        const currentMarginTop = block.marginTop;
        const distanceToNextPage = ((startPage + 1) * PAGE_HEIGHT) - relativeTop;
        block.marginTop = currentMarginTop + distanceToNextPage + 20;
      }
    });

    const finalLayout = getLayout();
    console.log('Final Layout:', finalLayout);

    // Parent2 was 800 to 1400 (crosses 1122.5). 
    // It should NOT be pushed because its height > PAGE_HEIGHT?
    // Wait, (relativeBottom - relativeTop) < PAGE_HEIGHT
    // At start, parent2 is height 600. 600 < 1122.5. YES, IT IS PUSHED!

    // If parent2 is pushed, it moves to start of Page 2 (1122.5 + 20 = 1142.5).
    // Let's see if this creates a huge gap.
  });
});

import { useEffect, useMemo, useRef, useState, useCallback, type MouseEvent } from "react";
import { FileText, Linkedin, LogIn, LogOut, Sparkles, Target, Zap, Star, ArrowRight, Menu, X, TrendingUp, MessageSquare, BarChart3, Mail, Crown, Gift, ShieldCheck, Sun, Moon, Settings } from "lucide-react";
import { useTranslation } from "react-i18next";
import { cn } from "../../lib/utils/cn";
import { useAuth } from "../../hooks/useAuth";
import { getSkylineUrl } from "../../lib/assets";
import { LanguageSwitcher } from "../ui/LanguageSwitcher";
import { GlassButton } from "../ui/GlassButton";
import { CreditBalance } from "../Credits/CreditBalance";
import { CreditUsageModal } from "../Credits/CreditUsageModal";
import { SettingsModal } from "../Settings/SettingsModal";
import { useTheme } from "../../hooks/useTheme";
import { createPortal } from "react-dom";



const containerClass = "app-shell w-full";

const getPrefersReducedMotion = () => {
  if (typeof window === "undefined") return false;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
};

// Modern premium glass card styles
const glassCardClass =
  "neu-card group";

const glassCardHoverClass =
  "neu-card-hover";

// Icon circle with glow effect
const iconCircleClass =
  "relative inline-flex items-center justify-center rounded-full bg-gradient-to-br from-emerald-500/20 to-teal-500/10 border border-emerald-400/30 shadow-[0_0_20px_rgba(16,185,129,0.3)] backdrop-blur-xl transition-all duration-300";

export default function Header() {
  const { t } = useTranslation();
  const { user, signInWithGoogle, signOut } = useAuth();
  const skylineUrl = useMemo(() => getSkylineUrl(), []);
  const [skylineLoaded, setSkylineLoaded] = useState(false);
  const [animateSkyline, setAnimateSkyline] = useState(false);
  const isFallbackSkyline = useMemo(
    () => typeof skylineUrl === "string" && skylineUrl.startsWith("data:image/"),
    [skylineUrl]
  );
  const initialReducedMotion = useMemo(getPrefersReducedMotion, []);
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(initialReducedMotion);
  const [heroVisible, setHeroVisible] = useState(initialReducedMotion);
  const [workflowVisible, setWorkflowVisible] = useState(initialReducedMotion);
  const heroAnimatedRef = useRef(initialReducedMotion);
  const workflowAnimatedRef = useRef(initialReducedMotion);
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [mobileNavOpen, setMobileNavOpen] = useState(false);
  const [badgeFlipped, setBadgeFlipped] = useState(false);
  const mobileNavRef = useRef<HTMLDivElement>(null);
  const [showCreditModal, setShowCreditModal] = useState(false);
  const [creditModalMode, setCreditModalMode] = useState<'full' | 'invite-only'>('full');
  const [showSettingsModal, setShowSettingsModal] = useState(false);

  const [theme, toggleTheme] = useTheme();

  // Mouse tracking for interactive gradient
  const handleMouseMove = useCallback((e) => {
    if (prefersReducedMotion) return;
    const rect = e.currentTarget.getBoundingClientRect();
    setMousePosition({
      x: ((e.clientX - rect.left) / rect.width) * 100,
      y: ((e.clientY - rect.top) / rect.height) * 100,
    });
  }, [prefersReducedMotion]);

  // Mobile nav body scroll lock
  useEffect(() => {
    if (mobileNavOpen) {
      document.body.classList.add('mobile-nav-open');
    } else {
      document.body.classList.remove('mobile-nav-open');
    }
    return () => document.body.classList.remove('mobile-nav-open');
  }, [mobileNavOpen]);

  // Close mobile nav on ESC key
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && mobileNavOpen) {
        setMobileNavOpen(false);
      }
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [mobileNavOpen]);

  // Close mobile nav on outside click
  const handleMobileNavOutsideClick = useCallback((e: MouseEvent) => {
    if (mobileNavRef.current && !mobileNavRef.current.contains(e.target as Node)) {
      setMobileNavOpen(false);
    }
  }, []);

  // Preload skyline image
  useEffect(() => {
    if (typeof window === "undefined" || !skylineUrl) return undefined;

    const img = new Image();
    img.onload = () => setSkylineLoaded(true);
    img.onerror = () => setSkylineLoaded(false);
    img.src = skylineUrl;

    return () => {
      img.onload = null;
      img.onerror = null;
    };
  }, [skylineUrl]);

  useEffect(() => {
    if (typeof window === "undefined" || !skylineUrl || !skylineLoaded || isFallbackSkyline) {
      return undefined;
    }

    setAnimateSkyline(true);
    const timer = setTimeout(() => setAnimateSkyline(false), 1800);
    return () => clearTimeout(timer);
  }, [isFallbackSkyline, skylineLoaded, skylineUrl]);

  useEffect(() => {
    if (typeof window === "undefined") return undefined;

    const mediaQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
    const updateFromMediaQuery = (event) => {
      const shouldReduce = event.matches;
      setPrefersReducedMotion(shouldReduce);

      if (shouldReduce) {
        heroAnimatedRef.current = true;
        workflowAnimatedRef.current = true;
        setHeroVisible(true);
        setWorkflowVisible(true);
      }
    };

    updateFromMediaQuery(mediaQuery);

    let heroFrame;
    let workflowTimer;

    const requestFrame =
      typeof window.requestAnimationFrame === "function"
        ? window.requestAnimationFrame.bind(window)
        : (callback) => setTimeout(callback, 16);

    const cancelFrame =
      typeof window.cancelAnimationFrame === "function"
        ? window.cancelAnimationFrame.bind(window)
        : clearTimeout;

    if (!mediaQuery.matches) {
      if (!heroAnimatedRef.current) {
        heroFrame = requestFrame(() => {
          setHeroVisible(true);
          heroAnimatedRef.current = true;
        });
      }

      if (!workflowAnimatedRef.current) {
        workflowTimer = setTimeout(() => {
          setWorkflowVisible(true);
          workflowAnimatedRef.current = true;
        }, 200);
      }
    }

    const removeMotionListener =
      typeof mediaQuery.addEventListener === "function"
        ? (() => {
          mediaQuery.addEventListener("change", updateFromMediaQuery);
          return () => mediaQuery.removeEventListener("change", updateFromMediaQuery);
        })()
        : (() => {
          mediaQuery.addListener(updateFromMediaQuery);
          return () => mediaQuery.removeListener(updateFromMediaQuery);
        })();

    return () => {
      removeMotionListener();
      if (heroFrame) cancelFrame(heroFrame);
      if (workflowTimer) clearTimeout(workflowTimer);
    };
  }, []);



  // Feature cards organized by priority and category
  const featureCards = [
    // ===== CORE AI FEATURES (Top Priority - Trust & Intelligence) =====
    {
      icon: Target,
      label: t("header.features.matchScore.label"),
      desc: t("header.features.matchScore.desc"),
      gradient: "from-emerald-400 to-teal-500",
    },
    {
      icon: ShieldCheck,
      label: t("header.features.antiHallucination.label"),
      desc: t("header.features.antiHallucination.desc"),
      gradient: "from-emerald-400 to-green-500",
      highlight: true,
    },
    {
      icon: Sparkles,
      label: t("header.features.aiOptimization.label"),
      desc: t("header.features.aiOptimization.desc"),
      gradient: "from-purple-400 to-pink-500",
    },

    // ===== WORKFLOW FEATURES (Secondary - Core Functionality) =====
    {
      icon: Zap,
      label: t("header.features.smartParsing.label"),
      desc: t("header.features.smartParsing.desc"),
      gradient: "from-yellow-400 to-orange-500",
    },
    {
      icon: TrendingUp,
      label: t("header.features.keywords.label"),
      desc: t("header.features.keywords.desc"),
      gradient: "from-blue-400 to-indigo-500",
    },
    {
      icon: FileText,
      label: t("header.features.templates.label"),
      desc: t("header.features.templates.desc"),
      gradient: "from-cyan-400 to-blue-500",
    },

    // ===== ADVANCED FEATURES (Tertiary - Value-Added Services) =====
    {
      icon: MessageSquare,
      label: t("header.features.interview.label"),
      desc: t("header.features.interview.desc"),
      gradient: "from-rose-400 to-red-500",
    },
    {
      icon: BarChart3,
      label: t("header.features.bulk.label"),
      desc: t("header.features.bulk.desc"),
      gradient: "from-amber-400 to-orange-500",
    },
    {
      icon: Mail,
      label: t("header.features.coverLetter.label"),
      desc: t("header.features.coverLetter.desc"),
      gradient: "from-violet-400 to-purple-500",
    },
    {
      icon: Star,
      label: t("header.features.vision2030.label"),
      desc: t("header.features.vision2030.desc"),
      gradient: "from-[#006C35] to-emerald-500",
      highlight: true,
    },
  ];

  const workflowSteps = [
    {
      icon: FileText,
      title: t("header.workflow.step1.title"),
      desc: t("header.workflow.step1.desc"),
    },
    {
      icon: Target,
      title: t("header.workflow.step2.title"),
      desc: t("header.workflow.step2.desc"),
    },
    {
      icon: Sparkles,
      title: t("header.workflow.step3.title"),
      desc: t("header.workflow.step3.desc"),
    },
    {
      icon: TrendingUp,
      title: t("header.workflow.step4.title"),
      desc: t("header.workflow.step4.desc"),
    },
    {
      icon: MessageSquare,
      title: t("header.workflow.step5.title"),
      desc: t("header.workflow.step5.desc"),
    },
    {
      icon: Mail,
      title: t("header.workflow.step6.title"),
      desc: t("header.workflow.step6.desc"),
    },
  ];

  return (
    <header
      className="hero-bg-animate relative isolate flex flex-col overflow-hidden text-gray-900 dark:text-white h-auto pb-4"
      onMouseMove={handleMouseMove}
    >
      {/* Animated background effects */}
      <div className="absolute inset-0 -z-10 overflow-hidden">
        {/* Interactive gradient that follows mouse */}
        <div
          className="absolute w-[600px] h-[600px] rounded-full blur-[60px] opacity-15 transition-all duration-1000 ease-out"
          style={{
            background: "radial-gradient(circle, rgba(16,185,129,0.4) 0%, transparent 70%)",
            left: `${mousePosition.x - 20}%`,
            top: `${mousePosition.y - 20}%`,
            transform: "translate(-50%, -50%)",
          }}
        />



        {/* Animated grid pattern */}
        <div
          className="absolute inset-0 opacity-[0.03]"
          style={{
            backgroundImage: `
              linear-gradient(rgba(255,255,255,0.1) 1px, transparent 1px),
              linear-gradient(90deg, rgba(255,255,255,0.1) 1px, transparent 1px)
            `,
            backgroundSize: '60px 60px',
          }}
        />

        {/* Noise texture overlay - reduced opacity for better text contrast */}
        <div className="absolute inset-0 opacity-[0.01] mix-blend-overlay bg-[url('data:image/svg+xml;base64,')]" />
      </div>

      {/* Skyline background - fixed to cover entire page */}
      {typeof skylineUrl === "string" && skylineUrl && (
        <div
          role="img"
          aria-label="Decorative skyline background"
          className={cn(
