  const handleResumeDataUpdate = useCallback((updates) => {
    setResumeData(prev => ({ ...prev, ...updates }));
  }, []);

  const handleExportPdf = useCallback(
    async (variant, exportMethod = "supabase") => {
      if (!resumeData?.plainText) {
        pushToast({
          type: "warning",
          title: t("toasts.addResume"),
          description: t("toasts.addResumeDesc"),
        });
        return;
      }

      const normalizedVariant = variant === "ats-plain" ? "ats-plain" : "styled";

      try {
        // Merge original resume with AI optimizations (Hard Overrides + Smart Match)
        const mergedResume = mergeResumeData(resumeData, {
          optimization: optimizationData,
          candidateProfile: null, // Add if available
        });

        // Get the HTML content from exportPdf (without triggering print)
        const htmlContent = await exportResumeToPdf({
          resumeDocument: mergedResume || resumeData, // Fallback to original if merge fails
          jobDescription,
          matchAnalysis,
          optimizations,
          keywords: optimizationKeywords,
          variant: normalizedVariant,
          skipPrint: true, // Don't trigger print, just return HTML
        });

        // Check export method
        if (exportMethod === "supabase" && isSupabaseExportAvailable()) {
          // Check if user is authenticated
          if (!user) {
            pushToast({
              type: "warning",
              title: t("toasts.signInRequired"),
              description: t("toasts.signInRequiredDesc"),
            });
            return;
          }

          // Export to Supabase Storage
          const result = await exportToSupabase({
            htmlContent,
            fileName: "Resume_Optimized",
            metadata: {
              variant: normalizedVariant,
              hasJobDescription: Boolean(jobDescription),
              hasOptimizations: optimizations.length > 0,
              matchScore: matchAnalysis?.score,
            },
          });

          pushToast({
            type: "success",
            title: t("toasts.savedToAccount"),
            description: `Your resume "${result.fileName}" has been saved securely.`,
          });

          if (result.signedUrl) {
            const link = document.createElement('a');
            link.href = result.signedUrl;
            link.download = result.fileName || 'Resume_Optimized.html';
            link.rel = 'noopener noreferrer';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
          }
        } else {
          // Fallback to print dialog if Supabase is not available or user not signed in
          await exportResumeToPdf({
            resumeDocument: mergedResume || resumeData,
            jobDescription,
            matchAnalysis,
            optimizations,
            keywords: optimizationKeywords,
            variant: normalizedVariant,
          });

          pushToast({
            type: "success",
            title: t("toasts.printDialogOpened"),
            description: t("toasts.printDialogOpenedDesc"),
          });
        }
      } catch (error) {
        console.error("Export error:", error);
        pushToast({
          type: "danger",
          title: t("toasts.exportFailed"),
          description: error?.message || "Unable to export resume. Please try again.",
        });
      }
    },
    [jobDescription, matchAnalysis, optimizationData, optimizations, optimizationKeywords, pushToast, resumeData, user, t]
  );

  const renderedToasts = useMemo(
    () =>
      toasts.map((toast) => (
        <Toast
          key={toast.id}
          title={toast.title}
          description={toast.description}
          type={toast.type}
          onDismiss={() => dismissToast(toast.id)}
        />
      )),
    [dismissToast, toasts]
  );

  const workspace = (
    <ParallaxContainer enableLayers={true} className="py-1">
      <div className="space-y-3 sm:space-y-3 text-ink-700 dark:text-surface-50">
        {/* Tab navigation - full width on mobile */}
        <div className="flex items-center justify-between gap-2">
          <div className="flex-1 min-w-0">
            <GlassTabs
              data-tour="features"
              tabs={tabs}
              activeValue={activeTab}
              onTabChange={handleTabChange}
              rightAction={resumeData?.plainText ? (
                <button
                  type="button"
                  onClick={handleClearAllData}
                  className="flex-shrink-0 group flex items-center gap-1.5 rounded-full px-3 py-1.5 text-[10px] sm:text-xs font-bold uppercase tracking-wider text-ink-500/70 hover:bg-danger-500/10 hover:text-danger-500 transition-all duration-200 dark:text-surface-50/60 dark:hover:bg-danger-400/10 dark:hover:text-danger-400"
                  title="Clear all saved data"
                >
                  <Trash2 className="w-3.5 h-3.5 transition-transform group-hover:scale-110" />
                  <span className="hidden sm:inline">{t("workspace.clearAll")}</span>
                </button>
              ) : undefined}
            />
          </div>
        </div>

        <div className="neu-card relative min-h-[420px] sm:min-h-[480px] p-4 sm:p-5 lg:p-6 transition-shadow duration-300 group">
          {activeTab === "resume" && (
            <UploadSection
              onParseResume={handleParseResume}
              resumeDocument={resumeData}
              onToast={handleUploadToast}
              onClear={handleClearResume}
            />
          )}
          {activeTab === "match" && (
            <LazyErrorBoundary label="Match section">
              <Suspense fallback={<SectionSkeleton />}>
                <MatchSection
                  onAnalyzeMatchAI={handleAnalyzeMatchAI}
                  matchAnalysis={matchAnalysis}
                  isAnalyzing={isAnalyzing}
                  hasResume={Boolean(resumeData?.plainText)}
                  resumeText={resumeData?.plainText || ''}
                  onToast={pushToast}
                  onClear={handleClearMatch}
                />
              </Suspense>
            </LazyErrorBoundary>
          )}
          {activeTab === "vision2030" && (
            <LazyErrorBoundary label="Vision 2030 section">
              <Suspense fallback={<SectionSkeleton />}>
                <Vision2030Section
                  resumeText={resumeData?.plainText || ''}
                  onToast={pushToast}
                />
              </Suspense>
            </LazyErrorBoundary>
          )}
          {activeTab === "optimize" && (
            <LazyErrorBoundary label="Optimize section">
              <Suspense fallback={<SectionSkeleton />}>
                <OptimizeSection
                  isPremium={isPremium}
                  optimizations={optimizations}
                  keywords={optimizationKeywords}
                  isOptimizing={isOptimizing}
                  onOptimize={handleOptimize}
                  onCopy={handleCopy}
                  previewUsed={previewUsed}
                  onUpgrade={handleUpgrade}
                  onExport={handleExportPdf}
                  canExport={Boolean(resumeData?.plainText)}
                  hasMatchAnalysis={Boolean(matchAnalysis && jobDescription)}
                  onClear={handleClearOptimizations}
                />
              </Suspense>
            </LazyErrorBoundary>
          )}

          {activeTab === "templates" && (
            <TemplateGallery
              resumeData={resumeData}
              optimizationData={optimizationData}
            />
          )}
          {activeTab === "interview" && (
            <LazyErrorBoundary label="Interview section">
              <Suspense fallback={<SectionSkeleton />}>
                <InterviewSection
                  jobDescription={jobDescription}
                  resumeText={resumeData?.plainText || ""}
                  matchAnalysis={matchAnalysis}
                  resumeData={resumeData}
                  onUpdate={handleResumeDataUpdate}
                />
              </Suspense>
            </LazyErrorBoundary>
          )}
          {activeTab === "bulk" && (
            <LazyErrorBoundary label="Bulk Analysis section">
              <Suspense fallback={<SectionSkeleton />}>
                <BulkAnalysisSection
                  jobDescription={jobDescription}
                />
              </Suspense>
            </LazyErrorBoundary>
          )}
          {activeTab === "cover-letter" && (
            <LazyErrorBoundary label="Cover Letter section">
              <Suspense fallback={<SectionSkeleton />}>
                <CoverLetterSection
                  resumeText={resumeData?.plainText || ""}
                  jobDescription={jobDescription}
                  resumeData={resumeData}
                />
              </Suspense>
            </LazyErrorBoundary>
          )}
        </div>

        {hasNextTab && (
          <div className="flex justify-center sm:justify-end mt-4">
            <GlassButton variant="secondary" onClick={handleContinue} className="justify-center">
              <ArrowRight className="w-4 h-4 me-2" />
              {t("workspace.continue")}
            </GlassButton>
          </div>
        )}

      </div>
    </ParallaxContainer>
  );

  if (!loading && !user && showLanding) {
    return (
      <div className="relative isolate z-20 flex-1 flex flex-col w-full h-full">
        <ToastContainer>{renderedToasts}</ToastContainer>
        <Suspense fallback={<SectionSkeleton />}>
          <LandingPage
            onGetStarted={() => {
              if (typeof window !== "undefined") {
                window.localStorage.setItem("watheq:landingSeen", "true");
              }
              signInWithGoogle();
            }}
          />
        </Suspense>
      </div>
    );
  }

  return (
    <main
      data-app-main
      className="relative isolate z-20 min-h-screen pb-16 sm:pb-24 lg:pb-32"
    >
      <ToastContainer>{renderedToasts}</ToastContainer>
      <ViewTextModal
        isOpen={viewTextModalOpen}
        onClose={() => setViewTextModalOpen(false)}
        text={resumeData?.plainText || ""}
      />

      {/* Delete All Data Confirmation Modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-gray-900/60 dark:bg-black/80 backdrop-blur-md animate-fade-in"
            onClick={() => setShowDeleteConfirm(false)}
            aria-hidden="true"
          />
          <div className="relative w-full max-w-md neu-card shadow-2xl rounded-2xl animate-scale-in overflow-hidden">
            <div className="flex items-center gap-3 p-5 border-b border-gray-200 dark:border-white/10">
              <div className="p-2 neu-inset rounded-lg bg-red-50 dark:bg-red-500/10 text-red-500 shrink-0">
                <AlertTriangle className="w-5 h-5" />
              </div>
              <h3 className="text-xl font-bold text-gray-900 dark:text-white">
                {t("workspace.deleteAllConfirm.title", "Delete All Data?")}
              </h3>
            </div>
            <div className="p-6">
              <p className="text-gray-600 dark:text-gray-400 mb-6 leading-relaxed">
                {t(
                  "workspace.deleteAllConfirm.description",
                  "This will permanently delete your uploaded resume, optimizations, and all saved progress. This action cannot be undone."
                )}
              </p>
              <div className="flex gap-3 justify-end">
                <button
                  onClick={() => setShowDeleteConfirm(false)}
                  className="flex-1 sm:flex-none px-4 py-2 font-medium rounded-xl transition-all duration-300 bg-gray-100 dark:bg-gray-900/80 hover:bg-gray-200 dark:hover:bg-black border border-gray-300/50 dark:border-white/10 text-gray-900 dark:text-white shadow-md active:scale-95"
                >
                  {t("common.cancel", "Cancel")}
                </button>
                <button
                  onClick={confirmDeleteAllData}
                  className="flex-1 sm:flex-none px-4 py-2 font-medium rounded-xl transition-all duration-300 bg-red-500 hover:bg-red-600 text-white shadow-[0_4px_15px_rgba(239,68,68,0.25)] hover:shadow-[0_8px_30px_rgba(239,68,68,0.4)] border border-red-400/20 flex items-center justify-center gap-2 active:scale-95"
                >
                  <Trash2 className="w-4 h-4" />
                  {t("workspace.deleteAllConfirm.confirm", "Delete All")}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
      <div className={`${containerClass} space-y-4 sm:space-y-10 lg:space-y-12 text-ink-700 dark:text-surface-50`}>
        <div className="neu-card p-4 sm:p-7 lg:p-8 transition-shadow duration-300 group">
          {flowProgress > 0 && (
            <div className="mb-6 h-1.5 w-full overflow-hidden rounded-full bg-smoke-50/70 dark:bg-zinc-900/50">
              <div
                className="h-full rounded-full bg-gradient-to-r from-primary-500 via-primary-600 to-primary-700 transition-all duration-300"
                style={{ width: `${flowProgress}%` }}
                aria-hidden="true"
              />
            </div>
          )}

          {loading ? (
            <div className="space-y-6">
              <div className="h-8 w-40 rounded-full bg-smoke-50/70" />
              <div className="h-96 w-full overflow-hidden rounded-[var(--radius-card)] bg-smoke-50/60">
                <div className="h-full w-1/2 animate-shimmer bg-gradient-to-r from-transparent via-surface-50/40 to-transparent" />
              </div>
            </div>
          ) : user ? (
            workspace
          ) : (
            <EmptyState
              icon={UserPlus}
              title={t("workspace.signInToUnlock")}
              description={t("workspace.signInDescription")}
              actions={
                <GlassButton
                  variant="secondary"
                  onClick={signInWithGoogle}
                  className="justify-center text-[15px] font-semibold"
                >
                  <LogIn className="w-4 h-4 me-2" />
                  {t("workspace.signInViaGoogle")}
                </GlassButton>
              }
            />
          )}
        </div>
        {isDev && aiDebug && (
          <section className="text-xs text-ink-500 dark:text-surface-50/70">
            <div className="rounded-2xl border border-gray-200 dark:border-white/10 bg-gray-100 dark:bg-white/5 backdrop-blur-md shadow-xl p-4 sm:p-5">
              <p className="font-semibold uppercase tracking-[0.24em] text-emerald-500">AI Debug</p>
              <dl className="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-7">
                <div>
                  <dt className="text-[10px] uppercase tracking-[0.24em] text-ink-500/70 dark:text-surface-50/60">Status</dt>
                  <dd className="mt-1 font-medium text-ink-700 dark:text-surface-50">{aiDebug.status}</dd>
                </div>
                <div>
                  <dt className="text-[10px] uppercase tracking-[0.24em] text-ink-500/70 dark:text-surface-50/60">Model</dt>
                  <dd className="mt-1 font-medium text-ink-700 dark:text-surface-50">{aiDebug.model ?? "–"}</dd>
                </div>
                <div>
                  <dt className="text-[10px] uppercase tracking-[0.24em] text-ink-500/70 dark:text-surface-50/60">
                    Temperature
                  </dt>
                  <dd className="mt-1 font-medium text-ink-700 dark:text-surface-50">
                    {typeof aiDebug.temperature === "number"
                      ? Number.isInteger(aiDebug.temperature)
                        ? aiDebug.temperature
                        : aiDebug.temperature.toFixed(2)
                      : aiDebug.temperature ?? "–"}
                  </dd>
                </div>
                <div>
                  <dt className="text-[10px] uppercase tracking-[0.24em] text-ink-500/70 dark:text-surface-50/60">Tokens</dt>
                  <dd className="mt-1 font-medium text-ink-700 dark:text-surface-50">
                    {aiDebug.tokens ?? "–"}
                    {aiDebug.maxOutputTokens ? ` / ${aiDebug.maxOutputTokens}` : ""}
                  </dd>
                </div>
                <div>
                  <dt className="text-[10px] uppercase tracking-[0.24em] text-ink-500/70 dark:text-surface-50/60">Latency</dt>
                  <dd className="mt-1 font-medium text-ink-700 dark:text-surface-50">
                    {aiDebug.latencyMs ? `${Math.round(aiDebug.latencyMs)} ms` : "–"}
                  </dd>
                </div>
                <div>
                  <dt className="text-[10px] uppercase tracking-[0.24em] text-ink-500/70 dark:text-surface-50/60">Status Code</dt>
                  <dd className="mt-1 font-medium text-ink-700 dark:text-surface-50">{aiDebug.statusCode ?? "–"}</dd>
                </div>
                <div>
                  <dt className="text-[10px] uppercase tracking-[0.24em] text-ink-500/70 dark:text-surface-50/60">Error Code</dt>
                  <dd className="mt-1 font-medium text-ink-700 dark:text-surface-50">{aiDebug.errorCode ?? "–"}</dd>
                </div>
              </dl>
              {aiDebug.requestId && (
                <p className="mt-3 break-words text-[10px] text-ink-400/80 dark:text-surface-50/50">
                  Request ID: {aiDebug.requestId}
                </p>
              )}
            </div>
          </section>
        )}
      </div>

      {/* Comparison Table - shown for all users */}
      <div className={`${containerClass} mt-16 mb-12`}>
        <div className="text-center mb-12 space-y-4">
          <div className="inline-block px-4 py-1.5 rounded-full bg-emerald-100/90 dark:bg-emerald-500/10 backdrop-blur-md border border-emerald-500/30 text-emerald-800 dark:text-emerald-400 text-sm font-bold tracking-wider uppercase shadow-sm">
            {t("landing.comparison.title", "Competitive Advantage")}
          </div>
          <h2 className="text-3xl md:text-4xl font-bold text-white drop-shadow-[0_0_8px_rgba(0,0,0,0.8)] dark:drop-shadow-[0_0_15px_rgba(0,0,0,0.8)]">
            {t("landing.comparison.title", "Why Choose Watheq?")}
          </h2>
          <p className="max-w-2xl mx-auto text-lg text-white dark:text-white/80 font-medium drop-shadow-[0_0_8px_rgba(0,0,0,0.8)] dark:drop-shadow-[0_0_10px_rgba(0,0,0,0.8)]">
            {t("landing.comparison.subtitle", "See how we stack up against generic resume tools")}
          </p>
        </div>
        <ComparisonTable />
      </div>

      {/* Pricing Section - shown for all users */}
      <div className={`${containerClass} mt-2`}>
        <Suspense fallback={<SectionSkeleton />}>
          <PricingSection />
        </Suspense>
      </div>
    </main>
  );
}

import { TrendingUp, Code2, Briefcase, GraduationCap, Users, Info, ChevronDown, ChevronUp } from 'lucide-react';
import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { motion, AnimatePresence } from 'framer-motion';
import { GlassCard } from './ui/GlassCard';

// New categorical scores structure
export interface CategoryScore {
    score: number;
    max: number;
    matched?: string[];
    missing?: string[];
    gaps?: string[];
    reasoning?: string;
}

export interface CategoryScoresData {
    hard_skills: CategoryScore;
    experience: CategoryScore;
    education: CategoryScore;
    soft_skills: CategoryScore;
}

// Legacy structure for backwards compatibility
export interface ScoreBreakdownData {
    base_score: number;
    skill_match_bonus: number;
    keyword_coverage_bonus: number;
    gap_penalties: number;
    final_score: number;
    score_explanation: string;
}

interface ScoreBreakdownProps {
    data?: ScoreBreakdownData | null;
    categoryScores?: CategoryScoresData | null;
    beforeScore: number;
    afterScore: number;
    isPlaceholderScore?: boolean;
    isPlaceholderImprovement?: boolean;
    className?: string;
}

const CATEGORY_CONFIG = {
    hard_skills: {
        icon: Code2,
        colorClass: 'text-blue-400',
        bgClass: 'bg-blue-500/20',
        barClass: 'bg-blue-500',
        variant: 'blue' as const
    },
    experience: {
        icon: Briefcase,
        colorClass: 'text-purple-400',
        bgClass: 'bg-purple-500/20',
        barClass: 'bg-purple-500',
        variant: 'purple' as const
    },
    education: {
        icon: GraduationCap,
        colorClass: 'text-amber-400',
        bgClass: 'bg-amber-500/20',
        barClass: 'bg-amber-500',
        variant: 'warning' as const
    },
    soft_skills: {
        icon: Users,
        colorClass: 'text-emerald-400',
        bgClass: 'bg-emerald-500/20',
        barClass: 'bg-emerald-500',
        variant: 'success' as const
    }
} as const;

export function ScoreBreakdown({
    data,
    categoryScores,
    beforeScore,
    afterScore,
    isPlaceholderScore = false,
    isPlaceholderImprovement = false,
    className = ''
}: ScoreBreakdownProps) {
    const { t, i18n } = useTranslation();
    const isArabic = i18n.language === 'ar';
    // Improvement calculation available but currently unused - kept for future features
    // const improvement = afterScore - beforeScore;
    const [expanded, setExpanded] = useState(true);

    // Use new categorical scores if available
    if (categoryScores) {
        const categories = [
            { key: 'hard_skills' as const, label: isArabic ? 'المهارات التقنية' : 'Hard Skills' },
            { key: 'experience' as const, label: isArabic ? 'الخبرة' : 'Experience' },
            { key: 'education' as const, label: isArabic ? 'التعليم' : 'Education' },
            { key: 'soft_skills' as const, label: isArabic ? 'المهارات الشخصية' : 'Soft Skills' }
        ];

        // Use the authoritative match analysis score as the displayed total.
        // The AI's category scores don't always sum consistently with its overall
        // score (e.g., categories sum to 25% while overall score is 15%).
        // beforeScore comes from the match analysis and is the source of truth.
        const totalScore = isPlaceholderScore ? 0 : beforeScore;

        return (
            <GlassCard className={className}>
                <div className="space-y-6">
                    <div className="flex items-center justify-between">
                        <div>
                            <h3 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                                <TrendingUp className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
                                {t('optimize.scoreBreakdown.title', 'Score Breakdown')}
                            </h3>
                            <p className="text-xs text-gray-600 dark:text-gray-400 mt-1">
                                {isArabic ? 'تحليل مفصل لدرجة مطابقة سيرتك الذاتية' : 'Detailed analysis of your resume match score'}
                            </p>
                        </div>
                        <div className="flex items-center gap-4">
                            <div className="flex flex-col items-end">
                                <motion.div
                                    initial={{ opacity: 0, scale: 0.8 }}
                                    animate={{ opacity: 1, scale: 1 }}
                                    transition={{ type: "spring", stiffness: 200, damping: 15 }}
                                    className="text-3xl font-bold bg-gradient-to-r from-emerald-400 to-teal-400 bg-clip-text text-transparent"
                                >
                                    {totalScore}
                                </motion.div>
                                <span className="text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    {t('optimize.scoreBreakdown.outOf', 'Out of 100')}
                                </span>
                            </div>
                            <motion.button
                                whileTap={{ scale: 0.9 }}
                                onClick={() => setExpanded(!expanded)}
                                className="p-1 rounded-lg hover:bg-gray-100 dark:hover:bg-white/5 transition-colors text-gray-500 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white"
                            >
                                <motion.div
                                    animate={{ rotate: expanded ? 0 : 180 }}
                                    transition={{ type: "spring", stiffness: 300, damping: 20 }}
                                >
                                    <ChevronUp className="w-5 h-5" />
                                </motion.div>
                            </motion.button>
                        </div>
                    </div>

                    <AnimatePresence initial={false}>
                        {expanded && (
                            <motion.div
                                initial={{ height: 0, opacity: 0 }}
                                animate={{ height: 'auto', opacity: 1 }}
                                exit={{ height: 0, opacity: 0 }}
                                transition={{ type: "spring", stiffness: 300, damping: 25 }}
                                className="overflow-hidden"
                            >
                                {/* Category Bars */}
                                <div className="space-y-3 pt-2">
                                    {categories.map((cat, idx) => {
                                        const catData = categoryScores[cat.key];
                                        if (!catData) return null;

                                        const config = CATEGORY_CONFIG[cat.key];
                                        const Icon = config.icon;
                                        // Ensure percentage doesn't exceed 100 visually
                                        const percentage = Math.min((catData.score / catData.max) * 100, 100);

                                        return (
                                            <motion.div
                                                key={cat.key}
                                                initial={{ x: -20, opacity: 0 }}
                                                animate={{ x: 0, opacity: 1 }}
                                                transition={{ delay: idx * 0.1, type: "spring", stiffness: 300, damping: 20 }}
                                                className="group relative p-4 rounded-xl bg-gray-50 dark:bg-white/5 border border-gray-200 dark:border-white/5 hover:border-gray-300 dark:hover:border-white/10 transition-colors duration-300"
                                            >
                                                <div className="flex items-center justify-between mb-3">
                                                    <div className="flex items-center gap-3">
                                                        <div className={`p-2 rounded-lg ${config.bgClass}`}>
                                                            <Icon className={`w-4 h-4 ${config.colorClass}`} />
                                                        </div>
                                                        <div>
                                                            <span className="text-sm font-medium text-gray-900 dark:text-white block">
                                                                {cat.label}
                                                            </span>
                                                        </div>
                                                    </div>
                                                    <div className="flex items-baseline gap-1">
                                                        <span className={`text-base font-bold ${config.colorClass}`}>
                                                            {catData.score}
                                                        </span>
                                                        <span className="text-xs text-gray-500 dark:text-gray-400">/{catData.max}</span>
                                                    </div>
                                                </div>

                                                <div className="h-2 w-full bg-gray-200 dark:bg-black/40 rounded-full overflow-hidden ring-1 ring-gray-300 dark:ring-white/5">
                                                    <motion.div
                                                        initial={{ width: 0 }}
                                                        animate={{ width: `${percentage}%` }}
                                                        transition={{
                                                            type: "spring",
                                                            stiffness: 60,
                                                            damping: 15,
                                                            delay: 0.2 + (idx * 0.1)
                                                        }}
                                                        className={`h-full rounded-full relative overflow-hidden ${config.barClass}`}
                                                    >
                                                        {/* Auto shimmer on load, hover shimmer for interaction */}
                                                        <motion.div
                                                            animate={{ x: ['-100%', '200%'] }}
                                                            transition={{ repeat: Infinity, duration: 2, ease: "linear" }}
                                                            className="absolute inset-0 bg-gradient-to-r from-transparent via-white/30 to-transparent skew-x-12"
                                                        />
                                                    </motion.div>
                                                </div>

                                                {catData.reasoning && (
                                                    <p className="mt-3 text-xs text-gray-600 dark:text-gray-400 leading-relaxed pl-1 border-l-2 border-gray-200 dark:border-white/5">
                                                        {catData.reasoning}
                                                    </p>
                                                )}
                                            </motion.div>
                                        );
                                    })}
                                </div>

                                {/* Calculation Logic Footer - Grid Layout */}
                                <div className="mt-6 pt-5 border-t border-gray-200 dark:border-white/5 pb-2">
                                    <div className="flex items-center gap-2 mb-4">
                                        <Info className="w-4 h-4 text-blue-400" />
                                        <span className="text-xs font-semibold text-blue-400 uppercase tracking-wider">
                                            {t ? t('sections.match.calculation.title', 'Scoring Logic') : 'Scoring Logic'}
                                        </span>
                                    </div>
                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                        <div className="p-3 rounded-xl bg-gray-50 dark:bg-white/5 border border-gray-200 dark:border-white/5 hover:bg-gray-100 dark:hover:bg-white/10 transition-colors">
                                            <span className="text-xs font-bold text-blue-600 dark:text-blue-400 block mb-1">
                                                {isArabic ? 'المهارات التقنية' : 'Hard Skills'}
                                            </span>
                                            <p className="text-[11px] text-gray-600 dark:text-gray-400 leading-relaxed">
                                                {isArabic
                                                    ? 'يقيس تطابق الكلمات المفتاحية التقنية والأدوات المذكورة في الوصف الوظيفي.'
                                                    : 'Measures the match of technical keywords and tools mentioned in the job description.'}
                                            </p>
                                        </div>
                                        <div className="p-3 rounded-xl bg-gray-50 dark:bg-white/5 border border-gray-200 dark:border-white/5 hover:bg-gray-100 dark:hover:bg-white/10 transition-colors">
                                            <span className="text-xs font-bold text-purple-600 dark:text-purple-400 block mb-1">
                                                {isArabic ? 'الخبرة' : 'Experience'}
                                            </span>
                                            <p className="text-[11px] text-gray-600 dark:text-gray-400 leading-relaxed">
                                                {isArabic
                                                    ? 'يحلل المسميات الوظيفية السابقة وسنوات الخبرة ومدى صلتها بالدور المطلوب.'
                                                    : 'Analyzes past job titles, years of experience, and relevance to the target role.'}
                                            </p>
                                        </div>
                                        <div className="p-3 rounded-xl bg-gray-50 dark:bg-white/5 border border-gray-200 dark:border-white/5 hover:bg-gray-100 dark:hover:bg-white/10 transition-colors">
                                            <span className="text-xs font-bold text-amber-600 dark:text-amber-400 block mb-1">
                                                {isArabic ? 'التعليم' : 'Education'}
                                            </span>
                                            <p className="text-[11px] text-gray-600 dark:text-gray-400 leading-relaxed">
                                                {isArabic
                                                    ? 'يتحقق من المستوى الأكاديمي ومجال الدراسة للتأكد من استيفاء المتطلبات.'
                                                    : 'Checks academic level and field of study to ensure requirements are met.'}
                                            </p>
                                        </div>
                                        <div className="p-3 rounded-xl bg-gray-50 dark:bg-white/5 border border-gray-200 dark:border-white/5 hover:bg-gray-100 dark:hover:bg-white/10 transition-colors">
                                            <span className="text-xs font-bold text-emerald-600 dark:text-emerald-400 block mb-1">
                                                {isArabic ? 'المهارات الشخصية' : 'Soft Skills'}
                                            </span>
                                            <p className="text-[11px] text-gray-600 dark:text-gray-400 leading-relaxed">
                                                {isArabic
                                                    ? 'يكتشف السمات الشخصية والقيادية والتواصل من خلال سياق سيرتك الذاتية.'
                                                    : 'Detects behavioral, leadership, and communication traits from your resume context.'}
                                            </p>
                                        </div>
                                    </div>
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </div>
            </GlassCard>
        );
    }

    // Fallback: no categoryScores and no data — return null
    if (!data) {
        return null;
    }

    // Legacy breakdown display
    const breakdownItems = [
        {
            label: isArabic ? 'مطابقة الخبرة' : 'Experience Match',
            value: data.base_score,
            type: 'base' as const
        },
        {
            label: isArabic ? 'تغطية المهارات' : 'Skill Coverage',
            value: data.skill_match_bonus,
            type: 'bonus' as const
        },
        {
            label: isArabic ? 'مطابقة الكلمات المفتاحية' : 'Keyword Match',
            value: data.keyword_coverage_bonus,
            type: 'bonus' as const
        },
        {
            label: isArabic ? 'خصومات الفجوات' : 'Gap Penalties',
            value: -data.gap_penalties,
            type: 'penalty' as const
        },
    ];

    return (
        <GlassCard className={className}>
            <div className="space-y-4">
                <h3 className="text-lg font-semibold text-white">
                    {t('optimize.scoreBreakdown.title', 'Score Breakdown')}
                </h3>

                <div className="space-y-2">
                    {breakdownItems.map((item, index) => (
                        <div
                            key={index}
                            className="flex items-center justify-between py-2 border-b border-white/5 last:border-0"
                        >
                            <span className="text-sm text-gray-400">{item.label}</span>
                            <span className={`text-sm font-medium ${item.type === 'penalty'
                                ? 'text-red-400'
                                : item.type === 'bonus'
                                    ? 'text-emerald-400'
                                    : 'text-white'
                                }`}>
                                {item.type === 'base' ? '' : item.value >= 0 ? '+' : ''}
                                {item.value}
                            </span>
                        </div>
                    ))}
                    <div className="flex items-center justify-between py-2 border-t border-white/20">
                        <span className="text-sm font-semibold text-white">
                            {t('optimize.scoreBreakdown.finalScore', 'Final Score')}
                        </span>
                        <span className="text-lg font-bold text-emerald-400">
                            {data.final_score}%
                        </span>
                    </div>
                </div>

                {data.score_explanation && (
                    <p className="text-sm text-gray-400 italic">
                        {data.score_explanation}
                    </p>
                )}
            </div>
        </GlassCard>
    );
}

import { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { useTranslation } from 'react-i18next';
import { X, Settings, Download, Trash2, AlertTriangle, CheckCircle2 } from 'lucide-react';
import { useAuth } from '../../hooks/useAuth';
import { cn } from '../../lib/utils/cn';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function SettingsModal({ isOpen, onClose }: SettingsModalProps) {
  const { t } = useTranslation();
  const { user, signOut } = useAuth();
  const [isExporting, setIsExporting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!isOpen || !user || !mounted) return null;

  const handleDeleteAccount = async () => {
    setIsDeleting(true);
    setError(null);
    try {
      const { supabase } = await import('../../services/supabase');
      const { data } = await supabase.auth.getSession();

      const token = data.session?.access_token;
      if (!token) throw new Error('Could not get authentication token from active session.');

      const response = await fetch('/.netlify/functions/user-data-api', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify({ action: 'delete', confirmDelete: true }),
      });

      if (!response.ok) {
        let errorData = 'Failed to delete account';
        try {
           const json = await response.json();
           errorData = json.error || json.message || errorData;
        } catch(e) { /* ignore */ }
        throw new Error(errorData);
      }

      // Success, sign out automatically
      await signOut();
      onClose();
    } catch (err: any) {
      setError(err.message || 'An error occurred while deleting account.');
      setIsDeleting(false);
      setShowDeleteConfirm(false);
    }
  };

  const handleExportClick = async () => {
    try {
      setIsExporting(true);
      setError(null);
      const { supabase } = await import('../../services/supabase');
      const { data } = await supabase.auth.getSession();

      const token = data.session?.access_token;
      if (!token) throw new Error('Could not get authentication token from active session.');

      const response = await fetch('/.netlify/functions/user-data-api', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify({ action: 'export' }),
      });

      if (!response.ok) {
        throw new Error(`Failed to export data: ${response.status} ${response.statusText}`);
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `watheq-data-export-${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      a.remove();
    } catch (err: any) {
      setError(err.message || 'An error occurred while exporting data.');
    } finally {
      setIsExporting(false);
    }
  };

  const modal = (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-gray-900/60 dark:bg-black/80 backdrop-blur-md animate-fade-in"
        onClick={() => !isDeleting && onClose()}
      />

      {/* Modal */}
      <div className="relative w-full max-w-lg neu-card shadow-2xl rounded-2xl animate-scale-in overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between p-5 border-b border-gray-200 dark:border-white/10">
          <div className="flex items-center gap-3 text-gray-900 dark:text-white">
            <div className="p-2 neu-inset rounded-lg">
              <Settings className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
            </div>
            <h2 className="text-xl font-bold">Settings</h2>
          </div>
          <button
            onClick={onClose}
            disabled={isDeleting}
            className="p-2 text-gray-400 hover:text-gray-900 dark:hover:text-white rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition-colors disabled:opacity-50"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto max-h-[75vh]">
          {error && (
            <div className="mb-6 p-4 bg-red-50 dark:bg-red-500/10 border border-red-200 dark:border-red-500/20 text-red-600 dark:text-red-400 rounded-xl text-sm flex items-start gap-3">
              <AlertTriangle className="w-5 h-5 shrink-0" />
              <p>{error}</p>
            </div>
          )}

          {/* Account Details */}
          <div className="mb-8">
            <h3 className="text-sm font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-4">Account Information</h3>
            <div className="p-4 neu-inset rounded-xl">
              <p className="text-gray-900 dark:text-white font-medium">{user.email}</p>
              <div className="mt-2 flex items-center gap-1.5 text-xs text-emerald-600 dark:text-emerald-400">
                <CheckCircle2 className="w-4 h-4" />
                <span>Verified Account</span>
              </div>
            </div>
          </div>

          {/* Data Actions */}
          <div>
            <h3 className="text-sm font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-4">Data & Privacy</h3>

            <div className="space-y-4">
              {/* Export Data */}
              <div className="flex flex-col sm:flex-row sm:items-center justify-between p-4 neu-inset rounded-xl gap-4">
                <div>
                  <h4 className="font-semibold text-gray-900 dark:text-white">Export Personal Data</h4>
                  <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">Download a copy of your resumes and optimizations in JSON format.</p>
                </div>
                <button
                  onClick={handleExportClick}
                  disabled={isExporting || isDeleting}
                  className="shrink-0 flex items-center justify-center gap-2 px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50 shadow-sm"
                >
                  {isExporting ? (
                    <span className="w-4 h-4 border-2 border-gray-400 border-t-transparent rounded-full animate-spin" />
                  ) : (
                    <Download className="w-4 h-4" />
                  )}
                  {isExporting ? 'Exporting...' : 'Export Data'}
                </button>
              </div>

              {/* Delete Account */}
              <div className="flex flex-col sm:flex-row sm:items-center justify-between p-4 bg-red-50/50 dark:bg-red-500/5 border border-red-100 dark:border-red-500/20 rounded-xl gap-4">
                <div>
                  <h4 className="font-semibold text-red-600 dark:text-red-400">Delete Account</h4>
                  <p className="text-sm text-red-500/80 dark:text-red-400/80 mt-1">Permanently delete your account and all associated data.</p>
                </div>

                {!showDeleteConfirm ? (
                  <button
                    onClick={() => setShowDeleteConfirm(true)}
                    disabled={isExporting || isDeleting}
                    className="shrink-0 flex items-center justify-center gap-2 px-4 py-2 bg-red-100 dark:bg-red-500/10 text-red-600 dark:text-red-400 hover:bg-red-200 dark:hover:bg-red-500/20 rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
                  >
                    <Trash2 className="w-4 h-4" />
                    Delete Account
                  </button>
                ) : (
                  <div className="shrink-0 flex flex-col gap-2">
                    <p className="text-xs font-semibold text-red-600 dark:text-red-400 text-center">Are you sure?</p>
                    <div className="flex gap-2">
                      <button
                        onClick={handleDeleteAccount}
                        disabled={isDeleting}
                        className="px-3 py-1.5 bg-red-600 text-white rounded-lg text-sm font-medium hover:bg-red-700 transition-colors disabled:opacity-50 flex items-center justify-center gap-2 min-w-[70px]"
                      >
                        {isDeleting ? (
                          <span className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                        ) : 'Yes'}
                      </button>
                      <button
                        onClick={() => setShowDeleteConfirm(false)}
                        disabled={isDeleting}
                        className="px-3 py-1.5 bg-gray-200 dark:bg-white/10 text-gray-700 dark:text-gray-300 rounded-lg text-sm font-medium hover:bg-gray-300 dark:hover:bg-white/20 transition-colors disabled:opacity-50"
                      >
                        Cancel
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  return createPortal(modal, document.body);
}

import { useState, useCallback, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { GlassCard } from '../ui/GlassCard';
import { GlassButton } from '../ui/GlassButton';
import { GlassCircle } from '../ui/GlassCircle';
import { GlassInput } from '../ui/GlassInput';
import {
  FileText,
  Wand2,
  Download,
  Copy,
  AlertCircle,
  CheckCircle2,
  Briefcase,
  Zap,
  BookOpen,
  Palette,
  Loader2,
  Edit3,
  UserCircle
} from 'lucide-react';
import { saveAs } from 'file-saver';
import { cn } from '../../lib/utils/cn';
import { analytics } from '../../services/analytics';
import { useResumeStore } from '../../lib/stores/resumeStore';
import { splitTextWithKeywords, shouldApplyBolding } from '../../lib/utils/keywordBolder';
import { useUserCredits } from '../../hooks/useUserCredits';
import { useFeatureTracking } from '../../hooks/useFeatureTracking';
import { UpgradeModal } from '../Credits/UpgradeModal';
import { ConfirmActionModal } from '../Credits/ConfirmActionModal';
import { FeedbackModal } from '../Feedback/FeedbackModal';
import type { ResumeSchema } from '../../types/resume';

const FUNCTION_BASE_PATH = '/.netlify/functions';
const GENERATE_ENDPOINT = `${FUNCTION_BASE_PATH}/generate-cover-letter`;
const STORAGE_KEY = 'airo:coverLetter';

// === Types ===
interface CoverLetterSectionProps {
  resumeText?: string;
  jobDescription?: string;
  resumeData?: ResumeSchema | null;
}

// Company name and hiring manager extraction functions removed
// These fields should be manually entered by the user, not auto-filled

// === Tone options ===
const tones = [
  { value: 'professional', label: 'Professional', labelAr: 'احترافي', icon: Briefcase, color: 'text-blue-400', bg: 'bg-blue-500/10', border: 'border-blue-500/20' },
  { value: 'enthusiastic', label: 'Enthusiastic', labelAr: 'متحمس', icon: Zap, color: 'text-yellow-400', bg: 'bg-yellow-500/10', border: 'border-yellow-500/20' },
  { value: 'formal', label: 'Formal', labelAr: 'رسمي', icon: BookOpen, color: 'text-purple-400', bg: 'bg-purple-500/10', border: 'border-purple-500/20' },
  { value: 'creative', label: 'Creative', labelAr: 'إبداعي', icon: Palette, color: 'text-pink-400', bg: 'bg-pink-500/10', border: 'border-pink-500/20' }
];

export function CoverLetterSection({ resumeText, jobDescription, resumeData }: CoverLetterSectionProps) {
  const { t, i18n } = useTranslation();
  const { credits, refetch: refetchCredits } = useUserCredits();
  const { trackFeatureUse, shouldShowFeedback, dismissFeedback } = useFeatureTracking();
  const isArabic = i18n.language === 'ar';

  const [coverLetter, setCoverLetter] = useState('');
  const [companyName, setCompanyName] = useState('');
  const [hiringManager, setHiringManager] = useState('');
  const [tone, setTone] = useState('professional');
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [wordCount, setWordCount] = useState(0);
  const [keyHighlights, setKeyHighlights] = useState<string[]>([]);
  const [copied, setCopied] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [showUpgradeModal, setShowUpgradeModal] = useState(false);
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [showFeedbackModal, setShowFeedbackModal] = useState(false);
  const [signatureName, setSignatureName] = useState('');

  // Auto-fill tracking removed - fields are now manual entry only

  // Load from localStorage
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        try {
          const data = JSON.parse(stored);
          setCoverLetter(data.coverLetter || '');
          setCompanyName(data.companyName || '');
          setHiringManager(data.hiringManager || '');
          setTone(data.tone || 'professional');
          setKeyHighlights(data.keyHighlights || []);
          setSignatureName(data.signatureName || '');
        } catch (e) {
          console.error('Failed to load cover letter:', e);
        }
      }
    }
  }, []);

  // Auto-fill signature from resume data
  useEffect(() => {
    if (resumeData?.basics?.name && !signatureName) {
      setSignatureName(resumeData.basics.name);
    }
  }, [resumeData?.basics?.name, signatureName]);

  // Update word count
  useEffect(() => {
    setWordCount(coverLetter ? coverLetter.trim().split(/\s+/).length : 0);
  }, [coverLetter]);

  // Auto-fill useEffect removed - company name and hiring manager should be manually entered

  // Simple change handlers for manual entry
  const handleCompanyChange = (value: string) => {
    setCompanyName(value);
  };

  const handleManagerChange = (value: string) => {
    setHiringManager(value);
  };

  const generateCoverLetterActual = useCallback(async () => {
    if (!resumeText || !jobDescription) {
      setError(t('sections.coverLetter.errors.missing', 'Please provide both resume and job description'));
      return;
    }

    setIsGenerating(true);
    setError(null);

    try {
      // Get authenticated headers (includes Authorization Bearer token)
      const { getAuthHeaders } = await import('../../lib/auth/authHeaders');
      const headers = await getAuthHeaders();

      const response = await fetch(GENERATE_ENDPOINT, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          resumeText,
          jobDescription,
          companyName: companyName || undefined,
          hiringManager: hiringManager || undefined,
          tone,
          language: i18n.language,
        }),
      });

      // Handle insufficient credits (403)
      if (response.status === 403) {
        setShowUpgradeModal(true);
        setIsGenerating(false);
        return;
      }

      if (!response.ok) throw new Error(`Failed to generate: ${response.statusText}`);
      const data = await response.json();
      if (data.error) throw new Error(data.error);

      let generatedKeyHighlights = data.keyHighlights || [];
      let generatedText = data.coverLetter || '';

      // Auto-format if blob (no newlines found but has length)
      if (generatedText.length > 100 && !generatedText.includes('\n')) {
        // Safe heuristic: split on clear transition words and salutations
        generatedText = generatedText
          .replace(/(Dear\s+[^,]+,)/g, "$1\n\n")
          // Split before common paragraph starters if they follow a period
          .replace(/([.!?])\s+(?=(?:In|The|I\s|As|My|This|Furthermore|However|Finally|While|With)\s)/g, "$1\n\n")
          .replace(/(Sincerely,|Best regards,|Respectfully,)/g, "\n\n$1");
      }

      // Calculate word count from the processed text
      const calculatedWordCount = data.wordCount || (generatedText.trim().split(/\s+/).length || 0);

      setCoverLetter(generatedText);
      setKeyHighlights(generatedKeyHighlights);
      setWordCount(calculatedWordCount);

      // Track cover letter generation
      analytics.trackCoverLetter(calculatedWordCount);

      // Save to localStorage
      if (typeof window !== 'undefined') {
        localStorage.setItem(STORAGE_KEY, JSON.stringify({
          coverLetter: data.coverLetter,
          companyName,
          hiringManager,
          tone,
          keyHighlights: data.keyHighlights,
          signatureName,
          generatedAt: new Date().toISOString()
        }));
      }

      // Track feature use for feedback prompt
      trackFeatureUse('cover-letter');

      // Check if we should show feedback modal (with 5-10 second delay for better UX)
      if (shouldShowFeedback) {
        const delay = 5000 + Math.random() * 5000; // Random 5-10 seconds
        setTimeout(() => {
          setShowFeedbackModal(true);
        }, delay);
      }

      // Refetch credits to update balance (credits were consumed by backend)
      setTimeout(() => refetchCredits(), 500);
    } catch (err) {
      setError((err as Error).message || t('sections.coverLetter.errors.failed', 'Failed to generate cover letter'));
    } finally {
      setIsGenerating(false);
    }
  }, [resumeText, jobDescription, companyName, hiringManager, tone, refetchCredits, trackFeatureUse, shouldShowFeedback, t, i18n.language]);

  // Wrapper function that shows confirmation modal first
  const generateCoverLetter = () => {
    if (!resumeText || !jobDescription) {
      setError(t('sections.coverLetter.errors.missing', 'Please provide both resume and job description'));
      return;
    }
    setShowConfirmModal(true);
  };

  // Handler for confirmed cover letter generation
  const handleConfirmGenerate = async () => {
    setShowConfirmModal(false);
    await generateCoverLetterActual();
  };

  const copyCoverLetter = async () => {
    try {
      await navigator.clipboard.writeText(coverLetter);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy:', err);
    }
  };

  const downloadCoverLetter = async () => {
    // Get keywords and bold preference from store
    const store = useResumeStore.getState();
    const keywords = store.optimizationMetrics?.jdKeywords || [];
    const boldKeywordsFlag = store.displayOptions?.boldKeywords ?? true;

    // Dynamic import docx to reduce bundle size
    const { Document, Packer, Paragraph, TextRun, AlignmentType, convertInchesToTwip, LineRuleType } = await import('docx');

    // Professional font settings - Times New Roman 12pt (size in half-points: 12 * 2 = 24)
    const fontConfig = { font: 'Times New Roman', size: 24 };
    const lineSpacing = { line: 276, lineRule: LineRuleType.AUTO }; // 1.15 line spacing

    // Helper to create TextRuns with keyword bolding
    const createTextRuns = (text: string): any[] => {
      const applyBolding = shouldApplyBolding(keywords, boldKeywordsFlag);

      if (!applyBolding) {
        return [new TextRun({ text, ...fontConfig })];
      }

      const segments = splitTextWithKeywords(text, keywords, 15); // Top 15 keywords
      return segments.map(segment =>
        new TextRun({
          text: segment.text,
          ...fontConfig,
          bold: segment.bold,
        })
      );
    };

    // Remove any existing greeting from the cover letter content to avoid duplication
    let cleanedContent = coverLetter.trim();
    // Remove greeting line if it exists (e.g., "Dear Hiring Manager," or "Dear [Name],")
    cleanedContent = cleanedContent.replace(/^Dear\s+[^,\n]+,?\s*/i, '');

    // Split into paragraphs and filter empty ones
    const contentParagraphs = cleanedContent.split(/\n\n+/).filter(p => p.trim());
    const docChildren: any[] = [];

    // Company name (bold, left-aligned)
    if (companyName) {
      docChildren.push(new Paragraph({
        children: [new TextRun({ text: companyName, bold: true, ...fontConfig })],
        alignment: AlignmentType.LEFT,
        spacing: { after: 200, ...lineSpacing }
      }));
    }

    // Date (formatted professionally)
    const currentDate = new Date().toLocaleDateString('en-US', {
      year: 'numeric', month: 'long', day: 'numeric'
    });
    docChildren.push(new Paragraph({
      children: [new TextRun({ text: currentDate, ...fontConfig })],
      spacing: { after: 400, ...lineSpacing }
    }));

    // Greeting
    const greeting = hiringManager ? `Dear ${hiringManager},` : 'Dear Hiring Manager,';
    docChildren.push(new Paragraph({
      children: [new TextRun({ text: greeting, ...fontConfig })],
      spacing: { after: 280, ...lineSpacing }
    }));

    // Body paragraphs (justified, proper spacing, with keyword bolding)
    contentParagraphs.forEach(para => {
      const trimmed = para.trim();
      if (!trimmed) return;
      docChildren.push(new Paragraph({
        children: createTextRuns(trimmed),
        spacing: { after: 280, ...lineSpacing },
        alignment: AlignmentType.JUSTIFIED
      }));
    });

    // Signature
    if (signatureName) {
      // "Sincerely,"
      docChildren.push(new Paragraph({
        children: [new TextRun({ text: 'Sincerely,', ...fontConfig })],
        spacing: { after: 600, ...lineSpacing } // Extra space before signature
      }));

      // Signature name (bold)
      docChildren.push(new Paragraph({
        children: [new TextRun({ text: signatureName, bold: true, ...fontConfig })],
        spacing: { after: 200, ...lineSpacing }
      }));
    }

    const doc = new Document({
      sections: [{
        properties: {
          page: {
            margin: {
              top: convertInchesToTwip(1),
              bottom: convertInchesToTwip(1),
              left: convertInchesToTwip(1),
              right: convertInchesToTwip(1)
            }
          }
        },
        children: docChildren
      }]
    });

    const blob = await Packer.toBlob(doc);

    // Generate filename with username and company name
    const username = resumeData?.basics?.name
      ?.toLowerCase()
      .replace(/\s+/g, '-')
      .replace(/[^a-z0-9-]/g, '') // Remove special chars
      || 'user';

    const companySlug = companyName
      ?.toLowerCase()
      .replace(/\s+/g, '-')
      .replace(/[^a-z0-9-]/g, '')
      || '';

    const filename = companySlug
      ? `cover-letter-${username}-${companySlug}.docx`
      : `cover-letter-${username}.docx`;

    saveAs(blob, filename);
  };

  // Empty state
  if (!resumeText || !jobDescription) {
    return (
      <GlassCard className="border-dashed border-gray-300 dark:border-white/10 bg-gray-50 dark:bg-white/5">
        <div className="py-12 text-center">
          <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-gray-100 dark:bg-white/5 flex items-center justify-center">
            <FileText className="w-8 h-8 text-gray-400 opacity-50" />
          </div>
          <h3 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
            {t('sections.coverLetter.emptyTitle', 'Missing Information')}
          </h3>
          <p className="text-gray-500 dark:text-gray-400 max-w-md mx-auto">
            {t('sections.coverLetter.emptyDesc', 'Upload your resume and add a job description to generate a tailored cover letter.')}
          </p>
        </div>
      </GlassCard>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Configuration */}
      <GlassCard className="overflow-hidden">
        <div className="flex items-center gap-4 mb-8">
          <GlassCircle size="lg" variant="indigo" className="shadow-lg shadow-indigo-500/20">
            <FileText className="w-6 h-6 text-indigo-600 dark:text-indigo-300" />
          </GlassCircle>
          <div>
            <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-1">
              {t('sections.coverLetter.title', 'Cover Letter Generator')}
            </h3>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              {t('sections.coverLetter.subtitle', 'Create a compelling, tailored cover letter using AI')}
            </p>
          </div>
        </div>

        <div className="space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <GlassInput
              label={`${t('sections.coverLetter.companyName', 'Company Name')} (${t('common.optional', 'Optional')})`}
